import { NextResponse } from "next/server";
import { z } from "zod";
import { assertListaBelongsToMarca, authzErrorResponse } from "@/lib/server/authz";
import { authorizedSiteBrand } from "@/app/api/marca/site/_helpers";
import { normalizeCandidateText } from "@/lib/marca/site-parser";

const CandidateSchema = z.object({ id: z.string().uuid(), text: z.string().trim().min(1), normalizedText: z.string().trim().min(1), sourceUrl: z.string().url(), sourceField: z.string().min(1), catalogEntryId: z.string().uuid() });
const InputSchema = z.object({ brandId: z.string().uuid(), targetListId: z.string().uuid(), batchId: z.string().uuid(), candidates: z.array(CandidateSchema).min(1).max(500) });

export async function POST(request: Request) {
  try {
    const input = InputSchema.parse(await request.json());
    const brand = await authorizedSiteBrand(input.brandId);
    await assertListaBelongsToMarca(input.targetListId, input.brandId, brand.profile);
    const { data: existingRows, error: existingError } = await brand.profile.supabase.from("keywords_kgr").select("id,keyword,lista_id,status").eq("lista_id", input.targetListId);
    if (existingError) throw existingError;
    const existing = new Map((existingRows || []).map(row => [normalizeCandidateText(row.keyword), row]));
    const uniqueCandidates = input.candidates.filter((candidate, index, all) => all.findIndex(item => item.normalizedText === candidate.normalizedText) === index);
    const toInsert = uniqueCandidates.filter(candidate => !existing.has(candidate.normalizedText));
    const importedAt = new Date().toISOString();
    const payload = toInsert.map(candidate => ({ keyword: candidate.text, results_allintitle: null, volume_search: null, kgr_score: null, intent: null, lista_id: input.targetListId, status: "bruto", analise_semantica: { site_origin: { source: "site/sitemap", brandId: input.brandId, sourceUrl: candidate.sourceUrl, catalogEntryId: candidate.catalogEntryId, extractedField: candidate.sourceField, batchId: input.batchId, importedAt } } }));
    if (payload.length) {
      const { error } = await brand.profile.supabase.from("keywords_kgr").insert(payload);
      if (error) throw error;
    }
    return NextResponse.json({ batchId: input.batchId, imported: toInsert.map(item => item.id), alreadyExists: uniqueCandidates.filter(item => existing.has(item.normalizedText)).map(item => item.id), duplicateInBatch: input.candidates.filter(item => uniqueCandidates.every(unique => unique.id !== item.id)).map(item => item.id), persisted: true, status: "imported" });
  } catch (error) {
    const mapped = authzErrorResponse(error); return NextResponse.json({ error: mapped.message }, { status: mapped.status === 500 ? 422 : mapped.status });
  }
}
